START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20260730115450_AddTruckStockTemplates') THEN
    CREATE TABLE inventory."FgsTruckStockTemplate" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "TemplateCode" character varying(100) NOT NULL,
        "Name" character varying(200) NOT NULL,
        "Description" text,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsTruckStockTemplate" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsTruckStockTemplate_TenantId_CompanyId_TemplateCode" UNIQUE ("TenantId", "CompanyId", "TemplateCode"),
        CONSTRAINT "FK_FgsTruckStockTemplate_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES inventory."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
    );
    COMMENT ON TABLE inventory."FgsTruckStockTemplate" IS 'Defines reusable truck stock templates that specify the desired inventory configuration for service vehicles. Templates are used during truck commissioning and synchronization and do not store or create inventory themselves.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."Id" IS 'Unique identifier for the truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."TenantId" IS 'Identifies the tenant that owns this truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."CompanyId" IS 'Identifies the company that owns this truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."TemplateCode" IS 'Unique business code used to identify the truck stock template within a company.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."Name" IS 'User-friendly name of the truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."Description" IS 'Optional description explaining the intended purpose or usage of the truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."CreatedOn" IS 'Date and time when the truck stock template was created.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."CreatedBy" IS 'User who created the truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."UpdatedOn" IS 'Date and time when the truck stock template was last modified.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."UpdatedBy" IS 'User who last modified the truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplate"."IsActive" IS 'Indicates whether the truck stock template is available for use when commissioning or synchronizing truck inventory.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20260730115450_AddTruckStockTemplates') THEN
    CREATE TABLE inventory."FgsTruckStockTemplateItem" (
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TruckStockTemplateId" bigint NOT NULL,
        "InventoryItemId" bigint NOT NULL,
        "TargetQuantity" numeric(18,2) NOT NULL DEFAULT 0.0,
        "MinimumQuantity" numeric(18,2) NOT NULL DEFAULT 0.0,
        "DisplayOrder" integer NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        CONSTRAINT "PK_FgsTruckStockTemplateItem" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsTruckStockTemplateItem_Template_Item" UNIQUE ("TenantId", "CompanyId", "TruckStockTemplateId", "InventoryItemId"),
        CONSTRAINT "CK_FgsTruckStockTemplateItem_MinimumQuantity" CHECK ("MinimumQuantity" >= 0),
        CONSTRAINT "CK_FgsTruckStockTemplateItem_TargetGreaterThanMinimum" CHECK ("TargetQuantity" >= "MinimumQuantity"),
        CONSTRAINT "CK_FgsTruckStockTemplateItem_TargetQuantity" CHECK ("TargetQuantity" >= 0),
        CONSTRAINT "FK_FgsTruckStockTemplateItem_FgsInventoryItem" FOREIGN KEY ("InventoryItemId") REFERENCES inventory."FgsInventoryItem" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsTruckStockTemplateItem_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES inventory."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsTruckStockTemplateItem_FgsTruckStockTemplate" FOREIGN KEY ("TruckStockTemplateId") REFERENCES inventory."FgsTruckStockTemplate" ("Id") ON DELETE CASCADE
    );
    COMMENT ON TABLE inventory."FgsTruckStockTemplateItem" IS 'Defines the inventory items and desired stocking quantities for a truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."TenantId" IS 'Identifies the tenant that owns this truck stock template item.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."CompanyId" IS 'Identifies the company that owns this truck stock template item.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."Id" IS 'Unique identifier for the truck stock template item.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."TruckStockTemplateId" IS 'References the truck stock template that includes this inventory item.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."InventoryItemId" IS 'References the inventory item included in the truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."TargetQuantity" IS 'Desired quantity of the inventory item to stock on trucks using this template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."MinimumQuantity" IS 'Minimum warehouse quantity required before inventory can be transferred during truck commissioning or synchronization.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."DisplayOrder" IS 'Controls the display order of inventory items within the truck stock template.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."CreatedOn" IS 'Date and time when the truck stock template item was created.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."CreatedBy" IS 'User who created the truck stock template item.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."UpdatedOn" IS 'Date and time when the truck stock template item was last modified.';
    COMMENT ON COLUMN inventory."FgsTruckStockTemplateItem"."UpdatedBy" IS 'User who last modified the truck stock template item.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20260730115450_AddTruckStockTemplates') THEN
    CREATE INDEX "IX_FgsTruckStockTemplate_IsActive" ON inventory."FgsTruckStockTemplate" ("TenantId", "CompanyId", "IsActive");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20260730115450_AddTruckStockTemplates') THEN
    CREATE INDEX "IX_FgsTruckStockTemplate_TenantId_CompanyId_Name" ON inventory."FgsTruckStockTemplate" ("TenantId", "CompanyId", "Name");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20260730115450_AddTruckStockTemplates') THEN
    CREATE INDEX "IX_FgsTruckStockTemplateItem_InventoryItemId" ON inventory."FgsTruckStockTemplateItem" ("InventoryItemId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20260730115450_AddTruckStockTemplates') THEN
    CREATE INDEX "IX_FgsTruckStockTemplateItem_TenantId_CompanyId_TruckStockTemplateId" ON inventory."FgsTruckStockTemplateItem" ("TenantId", "CompanyId", "TruckStockTemplateId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20260730115450_AddTruckStockTemplates') THEN
    CREATE INDEX "IX_FgsTruckStockTemplateItem_TruckStockTemplateId" ON inventory."FgsTruckStockTemplateItem" ("TruckStockTemplateId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM inventory."__EFMigrationsHistory" WHERE "MigrationId" = '20260730115450_AddTruckStockTemplates') THEN
    INSERT INTO inventory."__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260730115450_AddTruckStockTemplates', '10.0.8');
    END IF;
END $EF$;
COMMIT;

